// Гибридный матчер (задача 002, ADR-0004).
// bge-m3 НЕ различает артикулы, отличающиеся одним знаком (калибровка
// 2026-10-07: «…18.42» к «…18.41» даёт score 0.92), поэтому:
//   1) артикул есть с обеих сторон и совпал  -> линкуем, method='article';
//   2) артикул есть с обеих сторон и РАЗЛИЧАЕТСЯ -> ВЕТО (другая модель),
//      кандидат вычёркивается независимо от score;
//   3) артикула нет хотя бы с одной стороны -> решает вектор (score >= T1),
//      method='vector'.
const T1 = 0.85; // утверждён владельцем по калибровке 2026-10-07 (ADR-0004)
const crypto = require('crypto');

const CYR2LAT = { 'А':'A','В':'B','С':'C','Е':'E','Н':'H','К':'K','М':'M','О':'O','Р':'P','Т':'T','Х':'X' };
function extractArticle(s) {
  if (!s) return null;
  const t = String(s).toUpperCase();
  // токен «буквы + цифры с разделителями» (ДПП22-20.137.18.41, ПВ3-10, PCAM_0744_000_114-102);
  // цифровые типоразмеры (14х1, 2050x1420x3) НЕ извлекаем — их решает вектор
  const m = t.match(/[A-ZА-Я][\dA-ZА-Я()]*(?:\s*[-._\/]\s*[\dA-ZА-Я()]+)+/g);
  if (!m || !m.length) return null;
  for (const cand of m.sort((a, b) => b.length - a.length)) {
    const norm = cand.replace(/[АВСЕНКМОРТХ]/g, ch => CYR2LAT[ch]).replace(/[^A-Z0-9А-Я]/g, '');
    if (/^(?=.*\d)[A-Z0-9А-Я]{4,}$/.test(norm)) return norm;
  }
  return null;
}
function uuid5(text) {
  const h = crypto.createHash('sha1').update(text).digest();
  h[6] = (h[6] & 0x0f) | 0x50;
  h[8] = (h[8] & 0x3f) | 0x80;
  const hex = h.toString('hex');
  return hex.slice(0, 8) + '-' + hex.slice(8, 12) + '-' + hex.slice(12, 16) + '-' + hex.slice(16, 20) + '-' + hex.slice(20, 32);
}
const rows = $input.all().map(x => x.json);
if (!rows.length) return [];

const ids = rows.map(r => uuid5('item:' + r.file_name + ':' + r.line_no));
const got = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://qdrant:6333/collections/invoice_items/points',
  body: { ids: ids, with_vector: true, with_payload: false },
  json: true
});
const vecById = {};
for (const p of (got.result || [])) vecById[String(p.id)] = p.vector;

const searchable = rows.map((r, i) => ({ r: r, id: ids[i], v: vecById[ids[i]] }))
  .filter(x => Array.isArray(x.v));
// Позиции без вектора пропускаем (link_processed НЕ ставим — повторит тиком).
if (!searchable.length) return [];

// top-5: артикульный кандидат может быть не первым по вектору
const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://qdrant:6333/collections/sku_catalog/points/search/batch',
  body: { searches: searchable.map(x => ({ vector: x.v, limit: 5, with_payload: true })) },
  json: true
});
const results = (resp.result || []);
if (results.length !== searchable.length) {
  throw new Error('SEARCH_MISMATCH: ожидалось ' + searchable.length + ' ответов, пришло ' + results.length);
}

const updates = searchable.map((x, i) => {
  const rowArt = extractArticle(x.r.item_name);
  const cands = (results[i] || []).map(h => ({
    code: h.payload ? String(h.payload.code) : null,
    name: h.payload ? String(h.payload.item_name) : null,
    score: Number(h.score),
    art: h.payload ? extractArticle(h.payload.item_name) : null
  }));
  let sku = null, method = null, score = null;
  if (rowArt) {
    // шаг 1: точное совпадение артикула
    const exact = cands.filter(c => c.art && c.art === rowArt)
      .sort((a, b) => b.score - a.score)[0];
    if (exact) {
      sku = exact.code; method = 'article'; score = exact.score;
    } else {
      // шаг 2: вето на чужой артикул; вектор — только по кандидатам без артикула
      const free = cands.filter(c => !c.art);
      const top = free.sort((a, b) => b.score - a.score)[0];
      if (top && top.score >= T1) { sku = top.code; method = 'vector'; score = top.score; }
      else if (top) { score = top.score; }
    }
  } else {
    // шаг 3: артикула в позиции нет — обычный векторный top-1
    const top = cands.sort((a, b) => b.score - a.score)[0];
    if (top) {
      score = top.score;
      if (top.score >= T1) { sku = top.code; method = 'vector'; }
    }
  }
  return { item_id: Number(x.r.item_id), sku_code: sku, link_score: score, link_method: method };
});
return [{ json: { updates: JSON.stringify(updates).replace(/'/g, "''"), matched: updates.filter(u => u.sku_code).length, total: updates.length } }];
